DATABASE_URL = os.getenv('DATABASE_URL')
if DATABASE_URL:
    import psycopg
    from psycopg.rows import dict_row

    class PostgresDatabase:
        def __init__(self, schema):
            self.connection = psycopg.connect(DATABASE_URL, row_factory=dict_row)
            self.schema = schema
            self.connection.execute('create schema if not exists ' + schema)
            self.commit()

        def execute(self, sql, params=()):
            self.connection.execute('set search_path to ' + self.schema)
            return self.connection.execute(sql.replace('?', '%s'), params)

        def executemany(self, sql, params):
            self.connection.execute('set search_path to ' + self.schema)
            cursor = self.connection.cursor()
            return cursor.executemany(sql.replace('?', '%s'), params)

        def executescript(self, sql):
            for statement in sql.split(';'):
                if statement.strip():
                    self.execute(statement)

        def commit(self):
            self.connection.commit()

        def rollback(self):
            self.connection.rollback()

    db = PostgresDatabase('production')
    hdb = PostgresDatabase('honeypot')
    INTEGER_ID = 'integer primary key generated by default as identity'
else:
    db = sqlite3.connect(DB, check_same_thread=False); db.row_factory = sqlite3.Row
    hdb = sqlite3.connect(HDB, check_same_thread=False); hdb.row_factory = sqlite3.Row
    INTEGER_ID = 'integer primary key autoincrement'
DB_LOCK, HDB_LOCK = RLock(), RLock()
def _x(c, lock, sql, a, one):
    with lock:
        try:
            cursor = c.execute(sql, a); r = cursor.fetchall() if cursor.description else []; c.commit()
        except Exception:
            c.rollback()
            raise
    return (dict(r[0]) if r else None) if one else [dict(x) for x in r]
def q(sql, a=(), one=False): return _x(db, DB_LOCK, sql, a, one)
def hq(sql, a=(), one=False): return _x(hdb, HDB_LOCK, sql, a, one)
