FN = ['Aarav', 'Diya', 'Kabir', 'Meera', 'Rohan', 'Isha', 'Vikram', 'Anaya', 'Arjun', 'Nisha', 'Rahul', 'Priya', 'Sanjay', 'Tara', 'Dev', 'Zoya']; LN = ['Sharma', 'Verma', 'Iyer', 'Khan', 'Patel', 'Singh', 'Rao', 'Das', 'Nair', 'Gupta']; CT = ['Mumbai', 'Delhi', 'Pune', 'Agra', 'Jaipur', 'Chennai']
def populate(c, r, decoys):  # production = real-looking bank data; honeypot = fake shadow data + decoy tables
    nm = lambda: r.choice(FN) + ' ' + r.choice(LN)
    c.executemany('insert into customers values(?,?,?,?)', [('C%d' % i, nm(), r.choice(CT), r.randint(5, 900) * 1000) for i in range(1, 31)])
    c.executemany('insert into transactions(cust,amount,ts) values(?,?,?)', [('C%d' % r.randint(1, 30), r.randint(1, 400) * 500, '2026-10-%02d' % r.randint(1, 27)) for _ in range(60)])
    if decoys:
        c.executemany('insert into swift_beneficiaries_2019(beneficiary,bank,swift_code,account) values(?,?,?,?)', [(nm(), r.choice(['Global Trade Bank', 'Meridian Bank', 'Orion Savings']), 'GTBK%s%02d' % (r.choice('INUSGB'), r.randint(10, 99)), '%010d' % r.randint(0, 10 ** 10 - 1)) for _ in range(40)])
        c.executemany('insert into ceo_salary_ledger(month,amount,bonus) values(?,?,?)', [('2025-%02d' % i, r.randint(40, 60) * 100000, r.choice([0, 0, 500000])) for i in range(1, 13)])
        c.executemany('insert into kyc_master_backup(name,pan,phone) values(?,?,?)', [(nm(), '%s%04d%s' % (''.join(r.choice('ABCDEFGHJK') for _ in range(5)), r.randint(0, 9999), r.choice('ABCDEFGHJK')), '9%09d' % r.randint(0, 10 ** 9 - 1)) for _ in range(40)])
        c.executemany('insert into vip_accounts_archive(name,balance) values(?,?)', [(nm(), r.randint(50, 900) * 100000) for _ in range(25)])
        c.executemany('insert into canary_customers(name,email) values(?,?)', [('CUST-99%02d %s' % (17 + i, nm()), 'canary%d@trap.invalid' % i) for i in range(5)])
    c.commit()
if not q('select 1 from customers limit 1', (), 1): populate(db, random.Random(1), False)
