try:  # ML: Isolation Forest trained on a synthetic "normal staff day" profile
    import numpy as np
    from sklearn.ensemble import IsolationForest
    g = np.random.default_rng(7); N = 3000
    IF = IsolationForest(n_estimators=100, contamination=.01, random_state=7).fit(np.c_[g.normal(10, 1.2, N), g.normal(10.13, .35, N), g.normal(22, 4.3, N), np.abs(g.normal(.5, .7, N)), np.abs(g.normal(2, 1.4, N))])
except Exception:
    IF = None

