app = FastAPI(title='AI Sentinel')
FAILS = {}
def U(authorization: str = Header(None)):
    r = q('select u.* from sessions s join users u on u.username=s.username where s.token=?', ((authorization or '').replace('Bearer ', ''),), 1)
    if not r: err(401, 'Login required')
    return r

# ---------- alerts / cases ----------
def cv(c):
    a = q('select score from alerts where id=?', (c['a'],), 1)
    return dict(id=c['id'], a=c['a'], e=c['e'], t=c['t'], open=c['open'], owner=c['owner'], outcome=c['outcome'], score=a['score'] if a else 0, notes=q("select count(*) n from cev where c=? and kind='note'", (c['id'],), 1)['n'])
def cev(c, kind, text, user): q('insert into cev(c,ts,"user",kind,text) values(?,?,?,?,?)', (c, ts(), user, kind, text))
def open_case(a, user='system'):
    if q('select 1 from cases where a=?', (a['id'],), 1): return None
    cid = 'C-%d' % (101 + q('select count(*) n from cases', (), 1)['n'])
    q('insert into cases values(?,?,?,?,?,?,?)', (cid, a['id'], a['e'], now(), 1, '', ''))
    cev(cid, 'opened', 'Case opened from alert #%s (risk %d)' % (a['id'], a['score']), user)
    return cv(q('select * from cases where id=?', (cid,), 1))
def store(e, rs, t, user, trig=None):
    sc = min(100, sum(r[2] for r in rs)); p = prefs()
    a = dict(id='A-%d' % nxt('seq'), e=e, trig=trig or max(rs, key=lambda r: r[2])[1], score=sc, st='Escalated' if p['auto'] and sc >= p['thr'] else 'New', t=t, r=';'.join('|'.join(map(str, x)) for x in rs))
    q('insert into alerts values(?,?,?,?,?,?,?)', tuple(a[k] for k in ('id', 'e', 'trig', 'score', 'st', 't', 'r')))
    c = open_case(a, user) if a['st'] == 'Escalated' else None
    log(user, 'new alert', '#%s score %d' % (a['id'], sc)); return a, c
def graph():
    top = {}; tc = {}; by = {}
    for a in q("select e,score from alerts where st!='Reviewed'"): top[a['e']] = max(top.get(a['e'], 0), a['score'])
    for r in q('select emp,cust from touch'): tc.setdefault(r['emp'], []).append(r['cust'])
    for e in top:
        for c in tc.get(e, []): by.setdefault(c, set()).add(e)
    links = []; adj = {}
    for e in top:
        for c in tc.get(e, []):
            s = len(by[c]) > 1; links.append(dict(source=e, target=c, suspicious=s))
            if s: adj.setdefault(e, set()).add(c); adj.setdefault(c, set()).add(e)
    seen = set(); rings = []
    for n in adj:
        if n in seen: continue
        comp = []; stk = [n]; seen.add(n)
        while stk:
            x = stk.pop(); comp.append(x)
            for y in adj[x]:
                if y not in seen: seen.add(y); stk.append(y)
        if len(comp) >= 3: rings.append(sorted(comp))
    return dict(nodes=[dict(id=e, kind='employee', score=s) for e, s in top.items()] + [dict(id=c, kind='customer', score=0) for c in by], links=links, rings=rings)
def cdet(c):
    return dict(case=cv(c), alert=q('select * from alerts where id=?', (c['a'],), 1), emp=dict(zip(('name', 'dept'), q('select name,dept from emp where id=?', (c['e'],), 1).values()), id=c['e']),
                customers=[r['cust'] for r in q('select cust from touch where emp=?', (c['e'],))], events=[dict(ts=r['ts'], user=r['user'], kind=r['kind'], text=r['text']) for r in q('select * from cev where c=? order by id desc', (c['id'],))])
def case(cid): return q('select * from cases where id=?', (cid,), 1) or err(404, 'Case not found')
OUT = ['', 'Confirmed fraud', 'False positive', 'Inconclusive']

# ---------- auth ----------
@app.get('/api/health')
async def health(): return {'ok': True}
@app.post('/api/login')
async def login(b: dict = Body(...)):
    n = str(b.get('username', '')); f = FAILS.get(n, (0, 0))
    if f[0] >= 5 and datetime.now().timestamp() - f[1] < 300: err(429, 'Too many attempts. Try again in 5 minutes')
    u = q('select * from users where username=?', (n,), 1)
    if not u or not secrets.compare_digest(u['pw'], hpw(str(b.get('password', '')), u['salt'])):
        FAILS[n] = (f[0] + 1, datetime.now().timestamp()); err(401, 'Wrong username or password')
    FAILS.pop(n, None); t = secrets.token_urlsafe(32); q('insert into sessions values(?,?)', (t, n)); log(n, 'login')
    return dict(token=t, user=dict(username=n, name=u['name'], role=u['role']))
@app.post('/api/register/verify')
async def reg_verify(b: dict = Body(...)):
    if not secrets.compare_digest(str(b.get('key', '')), KEY): err(403, 'Invalid access key')
    return {'ok': True}
@app.post('/api/register')
async def register(b: dict = Body(...)):
    import re
    if not secrets.compare_digest(str(b.get('key', '')), KEY): err(403, 'Invalid access key')
