# ---------- Honeypot / deception: central log -> ML risk score -> alert -> session isolation ----------
def hp_hit(b, user):
    d = next((x for x in HPD if x[0] == b.get('decoy')), None); e = b.get('emp'); act = b.get('act')
    if not q('select 1 from emp where id=?', (e,), 1): err(404, 'Employee not found')
    if not d: err(404, 'Decoy not found')
    if act not in HPW: err(422, 'Invalid action')
    try: hour = float(b.get('hour')); rows = max(1, min(10 ** 6, int(float(b.get('rows') or 1))))
    except Exception: err(422, 'Invalid access time or rows')
    if not 0 <= hour < 24: err(422, 'Invalid access time')
    dev = bool(b.get('new_device')); prior = hq('select count(*) c from hlog where emp=? and dec is not null', (e,), 1)['c']
    prev = max([r['score'] for r in q("select score from alerts where e=? and st!='Reviewed'", (e,))] + [0]) / 100
    f = [x for x in [('🪤', 'Touched decoy %s (no legitimate use)' % d[1], 1.2 + d[3] * .28), ('⚙️', act + ' operation', HPW[act] * 1.6), ('📦', '{:,} row(s) touched'.format(rows), min(1.5, math.log10(rows + 1) * .45)),
         ('🕑', 'Off-hours access at ' + clk(hour), 1.1 if hour < 6 or hour >= 20 else 0), ('💻', 'Unknown device', .9 if dev else 0), ('🔁', 'Repeat decoy hits (%d)' % (prior + 1), min(prior, 3) * .3), ('📈', 'Already flagged by behaviour model', prev * .8)] if x[2] > 0]
    T = sum(x[2] for x in f); sc = max(1, min(100, round(100 / (1 + math.exp(2.4 - T)))))
    rs = [[x[0], x[1], max(1, round(sc * x[2] / T))] for x in f]; rs[0][2] = max(1, rs[0][2] + sc - sum(r[2] for r in rs))
    s = hq("select * from hsess where emp=? and state in ('Active','Isolated')", (e,), 1)
    if not s:
        sid = 'S-%d' % nxt('hseq'); hq('insert into hsess values(?,?,?,?,?,?,?,?)', (sid, e, '10.4.%d.%d' % (random.randint(0, 8), random.randint(10, 209)), 'Unknown device' if dev else 'Known device', clk(hour), 'Active', 0, 0)); s = hq('select * from hsess where id=?', (sid,), 1)
    was = s['state'] == 'Isolated'; hq('update hsess set hits=hits+1,sbq=sbq+?,dev=? where id=?', (int(was), 'Unknown device' if dev else s['dev'], s['id']))
    a, c = store(e, rs, clk(hour), user, 'Honeypot: ' + d[1]); iso = int(was); ms = 0
    if not was and q("select v from meta where k='hauto'", (), 1)['v'] == '1' and sc >= prefs()['thr']:
        hq("update hsess set state='Isolated' where id=?", (s['id'],)); iso = 1; ms = random.randint(300, 2500); log(user, 'auto-isolated session', s['id'])
    hq('insert into hlog(ts,emp,src,dec,obj,act,nrows,score,alert,iso,sess,ms) values(?,?,?,?,?,?,?,?,?,?,?,?)', (clk(hour), e, 'Decoy trigger', d[0], None, act, rows, sc, a['id'], iso, s['id'], ms))
    log(user, 'honeypot hit', '#%s %s score %d' % (a['id'], d[1], sc))
    return dict(alert=a, case=c, score=sc, isolated=iso, session=s['id'], message='Alert #%s created' % a['id'] + (' · session %s isolated automatically' % s['id'] if iso else ''))
@app.get('/api/honeypot')
async def hp_get(u=Depends(U)):
    L = hq('select * from hlog order by id desc'); names = {d[0]: d[1] for d in HPD}; ms = [l['ms'] for l in L if l['ms']]; ss = hq('select * from hsess order by id desc limit 12')
    return dict(auto=q("select v from meta where k='hauto'", (), 1)['v'] == '1', decoys=[dict(id=d[0], name=d[1], kind=d[2], sens=d[3], hits=sum(1 for l in L if l['dec'] == d[0])) for d in HPD],
                log=[dict(id='L-%d' % l['id'], ts=l['ts'], emp=l['emp'], src=l['src'], dec=l['dec'], obj=names.get(l['dec']) or l['obj'], act=l['act'], rows=l['nrows'], score=l['score'], alert=l['alert'], iso=l['iso'], sess=l['sess'], ms=l['ms']) for l in L[:40]],
                sess=ss, stats=dict(events=len(L), hits=sum(1 for l in L if l['dec']), isolated=sum(1 for s in ss if s['state'] == 'Isolated'), avg_ms=round(sum(ms) / len(ms)) if ms else 0))
