@app.post('/api/honeypot/sessions/{sid}/{act}')
async def hp_session(sid: str, act: str, u=Depends(U)):
    s = hq('select * from hsess where id=?', (sid,), 1)
    if act not in ('isolate', 'release', 'terminate'): err(404, 'Not found')
    if not s: err(404, 'Session not found')
    if s['state'] in ('Terminated', 'Released'): err(409, 'Session is already ' + s['state'].lower())
    hq('update hsess set state=? where id=?', ({'isolate': 'Isolated', 'release': 'Released', 'terminate': 'Terminated'}[act], sid))
    if act == 'isolate': hq('update hlog set iso=1 where sess=? and dec is not null', (sid,))
    log(u['username'], act + ' session', sid); return {'ok': True}

